@Transactional
public Long join(String username, int age) {
    Member m = new Member(username, age);
    m.setCreatedAt(LocalDateTime.now());
    m.setUpdatedAt(LocalDateTime.now());
    return memberRepository.save(m).getId();
}

@Transactional
public void rename(Long id, String name) {
    Member m = memberRepository.findById(id).orElseThrow();
    m.setUsername(name);
    m.setUpdatedAt(LocalDateTime.now());   // 이걸 자꾸 빠뜨린다
}

