@Test
@Transactional
void 빠뜨림() {
    Long id = memberService.join("m1", 10);
    em.flush(); em.clear();

    memberService.renameWithoutTouch(id, "바뀐이름");
    em.flush(); em.clear();

    Object[] row = (Object[]) em.createNativeQuery(
            "select username, updated_at from member where member_id = ?")
        .setParameter(1, id).getSingleResult();
    System.out.println("이름:   " + row[0]);
    System.out.println("수정일: " + row[1]);
}

