-- ① JPA 콜백으로 바꾼다

@MappedSuperclass
public abstract class JpaBaseEntity {

    @Column(updatable = false)
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    @PrePersist
    public void prePersist() {
        LocalDateTime now = LocalDateTime.now();
        createdAt = now;
        updatedAt = now;
    }

    @PreUpdate
    public void preUpdate() {
        updatedAt = LocalDateTime.now();
    }
}

@Entity
public class Member extends JpaBaseEntity { ... }

@Test
@Transactional
void 콜백() {
    Member m = memberRepository.save(new Member("m1", 10));
    em.flush();
    System.out.println("등록: " + m.getCreatedAt());
    System.out.println("수정: " + m.getUpdatedAt());

    m.setUsername("고침");
    em.flush();
    System.out.println("고친 뒤 수정: " + m.getUpdatedAt());
}

