void 등록일_고정() {
    Member m = memberRepository.save(new Member("m4", 10));
    em.flush();
    LocalDateTime first = m.getCreatedDate();

    m.setUsername("한번"); em.flush();
    m.setUsername("두번"); em.flush();

    System.out.println("처음:   " + first);
    System.out.println("지금:   " + m.getCreatedDate());
    System.out.println("같은가: " + first.equals(m.getCreatedDate()));
}

